local ActivityCakeShopTaskNodeCell = Class('ActivityCakeShopTaskNodeCell')
local ActivityCakeUtils = import('Game.UI.ActivityCakeShopDialog.ActivityCakeUtils')

function ActivityCakeShopTaskNodeCell:__init()

end

function ActivityCakeShopTaskNodeCell:__delete()

end

function ActivityCakeShopTaskNodeCell:Awake()
    SetButtonAction(self.BtnGoTo.gameObject,Bind(self,self.OnBtnCellClick))
end

function ActivityCakeShopTaskNodeCell:OnBtnCellClick()
    if self._isDraw then
        GameUtils.Toast(localize("已领取"))
        return
    end

    if self._isCanDraw and not self._isDraw then
        -- 领取
        if self.callBack then
            self.callBack(self.index)
        end
    else
        -- 前往
        if not isNull(self.vo) and checkNumber(self.vo.openType) > 0 then
            local row = GoodsConfMgr:GetInstance():GetJumpModuleRow(self.vo.openType)
            local t = checkTable(CfUtils.Split(self.vo.openParameter))
            GoodsConfMgr:GetInstance():ExecuteJump(row, nil, nil, nil, t)
        end
    end
end

function ActivityCakeShopTaskNodeCell:SetClickButtonAction(cb,index)
    self.callBack = cb
    self.index = index
end

function ActivityCakeShopTaskNodeCell:RefreshShow(data,taskType)
    self.data = data
    self.taskType = taskType
    local vo = self:GetTaskVo()

    self._No = checkBool(self.data.status == 0)
    self._isCanDraw = checkBool(self.data.status == 1)
    self._isDraw = checkBool(self.data.status == 2)
    self._isUnderWay = checkBool(self.data.status == 99)

    if not isNull(vo) then
        self.vo = vo
        CfUtils.FillText(self.TextDescribe,vo.desc)
        self.ProgressBar.value = checkNumber(self.data.progress) / checkNumber(vo.taskContenNum)
        CfUtils.FillText(self.ProgressNum, localize("<size=30><color=#545454>_num1_</color></size>/_num2_", {_num1_ = self.data.progress, _num2_ = vo.taskContenNum}))
        CfUtils.RefreshCommonGoodsListLight(self.CommonGoodsListLight, {[1] = {goodsId = vo.rewardId,num = vo.rewardNum }})
    end

    CfUtils.SetUISwitchImage(self.ImgFrame1,self._isCanDraw and 2 or 1)
    CfUtils.SetUISwitchImage(self.ImgFrame2,self._isCanDraw and 2 or 1)
    CfUtils.SetUISwitchImage(self.ImgSymbol1,self._isCanDraw and 2 or 1)
    CfUtils.SetUISwitchImage(self.ImgSymbol2,self._isCanDraw and 2 or 1)


    CfUtils.SetActive(self.BtnGoTo, not self._isDraw)
    local fontStyleBtn = KTool.GetComponent(self.BtnGoTo.gameObject ,typeof(CS.Game.Native.Common.FontStyleButton) )
    if self._isCanDraw and not self._isDraw then
        fontStyleBtn:ResetFontStyle("B12" , localize("领取"))
        KTool.SetActive(fontStyleBtn , true)
    elseif (not self._isDraw) then
        fontStyleBtn:ResetFontStyle("B13" , localize("前往"))
        KTool.SetActive(fontStyleBtn.gameObject , (not (checkInt(vo.openType)  <= 0)))
    else
        KTool.SetActive(fontStyleBtn.gameObject , false)
    end

    CfUtils.SetActive(self.UIFX_ActivityCompletion,self._isDraw)
    CfUtils.SetActive(self.Finish,self._isDraw)
    CfUtils.SetActive(self.Underway,self._isUnderWay)
    CfUtils.SetActive(self.TxtNo,self._No)
end

function ActivityCakeShopTaskNodeCell:GetTaskVo()
    local vo = nil
    if self.taskType == ActivityCakeUtils.TaskType.DailyTask then
        vo = ActivityCakeUtils.GetDailyTaskVoVo(self.data.id)
    elseif self.taskType == ActivityCakeUtils.TaskType.LimitTask then
        vo = ActivityCakeUtils.GetLimitTaskVo(self.data.id)
    end
    return vo
end

function ActivityCakeShopTaskNodeCell:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return ActivityCakeShopTaskNodeCell